package com.marketlabs.pulse.utils.extensions

// Generated by Claude Code.

import android.text.format.DateUtils

/**
 * Converts an epoch-millis timestamp into a relative "2 hours ago" / "Just now" style string.
 * Extracted from `NewsScreen.kt`'s `getTimeAgo()` so the Dashboard's news preview cards can render
 * the same relative timestamp format as the full News screen without duplicating the logic.
 */
fun Long.toRelativeTimeString(): String {
    return DateUtils.getRelativeTimeSpanString(
        this,
        System.currentTimeMillis(),
        DateUtils.MINUTE_IN_MILLIS,
        DateUtils.FORMAT_ABBREV_RELATIVE
    ).toString()
}
